import { expect, test } from '@playwright/test'
import { createClient, type SupabaseClient } from '@supabase/supabase-js'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { randomUUID } from 'node:crypto'
import { admin, adminCreateEvent, adminCreateGroup, cleanup, createTestUser, SUPABASE_URL, type TestUser } from './helpers/admin'

// Independent QA overlay: ordinary user sessions must enforce DB and Storage RLS.
const env = Object.fromEntries(readFileSync(resolve(import.meta.dirname, '../../.env'), 'utf8').trim().split('\n').map(line => { const i = line.indexOf('='); return [line.slice(0, i), line.slice(i + 1)] }))
if (SUPABASE_URL !== 'http://127.0.0.1:55431') throw new Error('Disposable local Supabase required')
let a: TestUser, b: TestUser, ca: SupabaseClient, cb: SupabaseClient
let ga: string, gb: string, eb: string
const files: string[] = []
function client(user: TestUser) {
  return createClient(SUPABASE_URL, env.VITE_SUPABASE_ANON_KEY, { global: { headers: { Authorization: `Bearer ${user.session.access_token}` } }, auth: { persistSession: false, autoRefreshToken: false } })
}
test.beforeAll(async () => {
  a = await createTestUser('QA group A'); b = await createTestUser('QA group B')
  ga = (await adminCreateGroup(a.id, 'QA A')).id; gb = (await adminCreateGroup(b.id, 'QA B')).id
  eb = await adminCreateEvent(gb, b.id, 'QA private B')
  ca = client(a); cb = client(b)
})
test.afterAll(async () => {
  if (files.length) await admin.storage.from('photos').remove(files)
  await cleanup([ga, gb].filter(Boolean), [a?.id, b?.id].filter(Boolean))
})
test('DB: owner allowed, foreign group select/insert/update/delete denied and data unchanged', async () => {
  const own = await cb.from('events').select('id,title').eq('id', eb)
  expect(own.error).toBeNull(); expect(own.data).toEqual([{ id: eb, title: 'QA private B' }])
  const foreign = await ca.from('events').select('id').eq('id', eb)
  expect(foreign.error).toBeNull(); expect(foreign.data).toEqual([])
  const insert = await ca.from('events').insert({group_id:gb,title:'unauthorized',type:'dinner',starts_at:new Date().toISOString(),created_by:a.id}).select('id')
  expect(insert.error?.code).toBe('42501')
  const update = await ca.from('events').update({title:'unauthorized'}).eq('id',eb).select('id')
  expect(update.error).toBeNull(); expect(update.data).toEqual([])
  const del = await ca.from('events').delete().eq('id',eb).select('id')
  expect(del.error).toBeNull(); expect(del.data).toEqual([])
  const after = await cb.from('events').select('id,title').eq('id',eb)
  expect(after.error).toBeNull(); expect(after.data).toEqual(own.data)
  const allowed = await ca.from('events').insert({group_id:ga,title:'owned',type:'dinner',starts_at:new Date().toISOString(),created_by:a.id}).select('id').single()
  expect(allowed.error).toBeNull(); expect(allowed.data?.id).toBeTruthy()
})
test('Storage: owner upload/download/delete allowed, foreign read/write/delete cannot change file', async () => {
  const name = `${gb}/${eb}/${randomUUID()}.webp`; files.push(name)
  // Small valid 1x1 WebP fixture; storage does not call external processing.
  const bytes=Buffer.from('UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEADsD+JaQAA3AAAAAA','base64')
  const uploaded=await cb.storage.from('photos').upload(name,bytes,{contentType:'image/webp'})
  expect(uploaded.error).toBeNull()
  const own=await cb.storage.from('photos').download(name)
  expect(own.error).toBeNull(); expect(Buffer.from(await own.data!.arrayBuffer())).toEqual(bytes)
  const deniedRead=await ca.storage.from('photos').download(name)
  expect(deniedRead.error).not.toBeNull(); expect(deniedRead.data).toBeNull()
  const deniedSign=await ca.storage.from('photos').createSignedUrl(name,60)
  expect(deniedSign.error).not.toBeNull(); expect(deniedSign.data).toBeNull()
  const foreignName=`${gb}/${eb}/${randomUUID()}.webp`; files.push(foreignName)
  const deniedWrite=await ca.storage.from('photos').upload(foreignName,bytes,{contentType:'image/webp'})
  expect(deniedWrite.error).not.toBeNull()
  const deniedDelete=await ca.storage.from('photos').remove([name])
  expect(deniedDelete.data ?? []).toEqual([])
  const after=await cb.storage.from('photos').download(name)
  expect(after.error).toBeNull(); expect(Buffer.from(await after.data!.arrayBuffer())).toEqual(bytes)
  const removed=await cb.storage.from('photos').remove([name])
  expect(removed.error).toBeNull(); expect(removed.data).toHaveLength(1)
  expect((await cb.storage.from('photos').download(name)).error).not.toBeNull()
})

async function closedFixture(label: string) {
  const closedEvent = await adminCreateEvent(gb, b.id, `${label} closed`)
  const openEvent = await adminCreateEvent(gb, b.id, `${label} open`)
  async function expense(eventId: string) {
    const result = await cb.from('expenses').insert({event_id:eventId,payer_id:b.id,title:label,amount:100,created_by:b.id}).select('id').single()
    expect(result.error).toBeNull(); return result.data!.id as string
  }
  const lockedExpense = await expense(closedEvent), openExpense = await expense(openEvent)
  expect((await cb.from('expense_participants').insert({expense_id:lockedExpense,user_id:b.id,share_amount:100})).error).toBeNull()
  const closed = await cb.rpc('close_settlement',{p_event_id:closedEvent,p_transfers:[]})
  expect(closed.error).toBeNull()
  return {closedEvent,openEvent,lockedExpense,openExpense}
}
test('Settlement: closed direct amount change rejected, foreign reopen denied, owner reopen permits change',async()=>{
  const f=await closedFixture('ordinary lock')
  const denied=await cb.from('expenses').update({amount:200}).eq('id',f.lockedExpense)
  expect(denied.error?.code).toBe('P0001')
  expect((await cb.from('expenses').select('amount').eq('id',f.lockedExpense).single()).data?.amount).toBe(100)
  expect((await ca.rpc('reopen_settlement',{p_event_id:f.closedEvent})).error).not.toBeNull()
  expect((await cb.from('settlements').select('status').eq('event_id',f.closedEvent).single()).data?.status).toBe('closed')
  expect((await cb.rpc('reopen_settlement',{p_event_id:f.closedEvent})).error).toBeNull()
  expect((await cb.from('expenses').update({amount:200}).eq('id',f.lockedExpense)).error).toBeNull()
  expect((await cb.from('expenses').select('amount').eq('id',f.lockedExpense).single()).data?.amount).toBe(200)
})
test('Settlement: moving expense out of closed event must be rejected and original parent retained',async()=>{
  const f=await closedFixture('expense move')
  const moved=await cb.from('expenses').update({event_id:f.openEvent}).eq('id',f.lockedExpense).select('event_id')
  const after=await cb.from('expenses').select('event_id').eq('id',f.lockedExpense).single()
  const state=await cb.from('settlements').select('status').eq('event_id',f.closedEvent).single()
  console.log('expense move observation',JSON.stringify({error:moved.error?.code??null,movedToOpen:after.data?.event_id===f.openEvent,settlement:state.data?.status}))
  expect.soft(moved.error).not.toBeNull()
  expect.soft(after.data?.event_id).toBe(f.closedEvent)
  expect(state.data?.status).toBe('closed')
})
test('Settlement: moving participant out of closed expense must be rejected and original parent retained',async()=>{
  const f=await closedFixture('participant move')
  const moved=await cb.from('expense_participants').update({expense_id:f.openExpense}).eq('expense_id',f.lockedExpense).eq('user_id',b.id).select('expense_id')
  const after=await cb.from('expense_participants').select('expense_id').eq('expense_id',f.openExpense).eq('user_id',b.id)
  const original=await cb.from('expense_participants').select('expense_id').eq('expense_id',f.lockedExpense).eq('user_id',b.id)
  const state=await cb.from('settlements').select('status').eq('event_id',f.closedEvent).single()
  console.log('participant move observation',JSON.stringify({error:moved.error?.code??null,movedToOpen:after.data?.length===1,originalCount:original.data?.length,settlement:state.data?.status}))
  expect.soft(moved.error).not.toBeNull()
  expect.soft(original.data).toHaveLength(1)
  expect.soft(after.data).toHaveLength(0)
  expect(state.data?.status).toBe('closed')
})
